function pageFor(body) {
  const locator = {
    first() {
      return this;
    },
    nth() {
      return this;
    },
    filter() {
      return this;
    },
    count: async () => 0,
    isVisible: async () => false,
    textContent: async () => ''
  };
  return {
    url: () => 'https://chatgpt.com/checkout/openai_llc/synthetic',
    setDefaultTimeout() {},
    locator: () => locator,
    getByRole: () => locator,
    getByText: () => locator,
    frames: () => [],
    evaluate: async () => false,
    textContent: async () => body,
    waitForTimeout: async () => new Promise((resolve) => setTimeout(resolve, 25))
  };
}
