async function rpcServer(handle) {
  const server = http.createServer(async (req, res) => {
    if (req.headers['x-online-recharge-worker'] !== key) {
      res.writeHead(403);
      return res.end('{}');
    }
    const chunks = [];
    for await (const chunk of req) chunks.push(chunk);
    const body = JSON.parse(Buffer.concat(chunks).toString());
    await handle(body, (value) => {
      if (body.method === 'heartbeat' && value?.ok === true)
        value = { ...value, leaseExpiresAt: new Date(Date.now() + 90000).toISOString() };
      res.writeHead(200, { 'content-type': 'application/json' });
      res.end(JSON.stringify(value));
    });
  });
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  return {
    url: `http://127.0.0.1:${server.address().port}/rpc`,
    close: async () => {
      server.closeAllConnections();
      await new Promise((resolve) => server.close(resolve));
    }
  };
}
