        if (checked !== 'true' && !(checked === null && await radio.isChecked().catch(() => false))) {
            throw new Error(`定价页 Pro 档位未选中: ${plan} / ${label}`);
        }
        console.log(`✅ [步骤] 定价页已选择 Pro 档位: ${plan} (${label})`);
        return true;
