    return {
        country: code,
        currency: cfg.currency,
        label: cfg.label
    };
}

function getRegionBrowserProfile(regionCode) {
    const cfg = getRegionConfig(regionCode) || REGION_CONFIG[DEFAULT_REGION];
    return {
        locale: cfg.locale,
        timezoneId: cfg.timezone
    };
}

